class Fecha:
    def __init__(self, dia, mes, anio):
        self.dia = dia
        self.mes = mes
        self.anio = anio

    def texto(self):                      # método de instancia
        return f"{self.dia:02d}/{self.mes:02d}/{self.anio}"

    @classmethod
    def desde_texto(cls, cadena):         # método de clase: otro constructor
        dia, mes, anio = cadena.split("-")
        return cls(int(dia), int(mes), int(anio))

    @staticmethod
    def es_bisiesto(anio):                # método estático: una utilidad
        return anio % 4 == 0 and (anio % 100 != 0 or anio % 400 == 0)


