class Deposito:
    def __init__(self, capacidad):
        self.capacidad = capacidad
        self.litros = 0

    def llenar(self, litros):
        if litros <= 0:
            raise ValueError("La cantidad debe ser positiva")
        self.litros = min(self.capacidad, self.litros + litros)
        return self.litros

    def vaciar(self):
        self.litros = 0


d = Deposito(50)
print(d.llenar(30))
print(d.llenar(30))
try:
    d.llenar(-5)
except ValueError as e:
    print("Error:", e)

