class Temperatura:
    def __init__(self, celsius):
        self.celsius = celsius           # se valida desde el principio

    @property
    def celsius(self):
        return self._celsius

    @celsius.setter
    def celsius(self, valor):
        if valor < -273.15:
            raise ValueError("Por debajo del cero absoluto")
        self._celsius = valor

    @property
    def fahrenheit(self):                # calculada y de solo lectura
        return self.celsius * 9 / 5 + 32


