class Pares:
    def __init__(self, limite):
        self.limite = limite
        self.actual = 0

    def __iter__(self):
        return self

    def __next__(self):
        if self.actual > self.limite:
            raise StopIteration
        valor = self.actual
        self.actual += 2
        return valor


print(list(Pares(7)))
for n in Pares(4):
    print(n)

checks.test:
assert list(Pares(-1)) == [], "Si el límite es negativo, no hay pares"
it = Pares(2)
assert next(it) == 0 and next(it) == 2, "next() da los pares uno a uno"
try:
    next(it)
except StopIteration:
    pass
else:
    raise AssertionError("Al pasarse del límite, __next__ debe lanzar StopIteration")

